/// @brief 只封装一只演员的世界出生参数；HP/分数为原始点数，种子逐实例固定，随机 X 在出生时求值一次。
SpawnActors Spawn(Vector3 position,const behavior::Pattern& pattern,float health,int score,int item,bool mirrored,bool randomX,unsigned seed,int animation,bool retireOutside) {
    return {behavior::Spawn{.position=position,.pattern=pattern,.mirrored=mirrored,.randomX=randomX,.sourceHealth=health,
        .sourceScore=score,.seed=seed,.sourceItem=item,.visual=kOrb,.hitRadius=0.625F,.bulletBase=kNativeBulletBase,
        .laserBase=kNativeLaserBase,.defeatBase=kNativeDefeat,.fallback=kBlueBullet,.retireOutside=retireOutside,.retirementHeights=Vector2{-10.5F,10.5F},.initialAnimation=animation},1,0};
}
